423				allowedRec = &recs[i]
424			}
425		}
426		if allowedRec == nil || allowedRec.RequestedAt == "" {
427			t.Fatalf("允许记录未正确保存：%+v", recs)
428		}
429	}
430	
431	func TestReviewFreezesHistoricalReasons(t *testing.T) {
432		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
433		l := newTestLedger(t, clock)
434		mustRegister(t, l, "M-1", "万用表", 0.5)
435	
436		// 待校准且无证书时申请，被拒绝。
437		_, _ = l.RequestUse("M-1")
438		r, _ := l.Review("M-1")
439		if len(r.Rejections) != 1 {
440			t.Fatalf("应看到 1 条拒绝记录，得到 %d", len(r.Rejections))
441		}
442		frozen := append([]string(nil), r.Rejections[0].Reasons...)
443	
444		// 之后补录合格证书并切换为在用：当前可以使用，但历史拒绝原因不变。
445		_ = l.SetStatus("M-1", StatusInUse)
446		mustAddCert(t, l, CertificateInput{
447			InstrumentID: "M-1", Number: "C-1", CalDate: "2026-09-01",
448			Expiry: "2027-09-01", Method: "m", Error: 0, Summary: "s",
449		})
450		r, _ = l.Review("M-1")
451		if !r.CanUse {
452			t.Fatalf("补录合格证书并在用后应可使用，得到 %v", r.Reasons)
453		}
454		if len(r.Rejections) != 1 || !sameReasons(r.Rejections[0].Reasons, frozen) {
455			t.Fatalf("历史拒绝原因被改写：保存=%v 现在=%v", frozen, r.Rejections[0].Reasons)
456		}
457		if r.Latest == nil || r.Latest.Number != "C-1" {
458			t.Fatal("核对视图应包含最近证书")
459		}
460		if len(r.History) != 1 {
461			t.Fatalf("核对视图应包含全部历史证书，得到 %d", len(r.History))
462		}
463	}
464	
465	func TestPersistenceAndLedgerIsolation(t *testing.T) {
466		dir := t.TempDir()
467		pathA := filepath.Join(dir, "a.json")
468		pathB := filepath.Join(dir, "b.json")
469		clock := func() time.Time { return mustDate(t, "2026-10-02") }
470	
471		la, err := openAt(pathA, clock)
472		if err != nil {
473			t.Fatalf("open A: %v", err)
474		}
475		mustRegister(t, la, "ONLY-A", "台账A器具", 0.1)
476		lb, err := openAt(pathB, clock)
477		if err != nil {
478			t.Fatalf("open B: %v", err)
479		}
480		mustRegister(t, lb, "ONLY-B", "台账B器具", 0.2)
481	
482		// 退出后再次打开同一台账仍能继续查询和操作。
483		reopenedA, err := openAt(pathA, clock)
484		if err != nil {
485			t.Fatalf("reopen A: %v", err)
486		}
487		if reopenedA.findInstrument("ONLY-A") == nil {
488			t.Fatal("台账A重开后丢失登记数据")
489		}
490		if reopenedA.findInstrument("ONLY-B") != nil {
491			t.Fatal("不同台账的数据混入了 A")
492		}
493		if _, err := reopenedA.Review("ONLY-B"); !errors.Is(err, ErrNotFound) {
494			t.Fatalf("台账 A 中不应能查到 B 的器具，得到 %v", err)
495		}
496		reopenedB, _ := openAt(pathB, clock)
497		if reopenedB.findInstrument("ONLY-A") != nil || reopenedB.findInstrument("ONLY-B") == nil {
498			t.Fatal("台账B数据被 A 污染")
499		}
500	
501		// 在重开的台账 A 上继续操作并再次持久化。
502		if err := reopenedA.SetStatus("ONLY-A", StatusRetired); err != nil {
503			t.Fatalf("在重开的台账上操作失败: %v", err)
504		}
505		again, _ := openAt(pathA, clock)
506		if again.findInstrument("ONLY-A").Status != StatusRetired {
507			t.Fatal("重开后所做的操作没有保存")
508		}
509	}
510	
511	func TestInvalidWritesLeaveNoHalfRecords(t *testing.T) {
512		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
513		path := filepath.Join(t.TempDir(), "ledger.json")
514		l, err := openAt(path, clock.now)
515		if err != nil {
516			t.Fatalf("open: %v", err)
517		}
518		mustRegister(t, l, "M-1", "万用表", 0.5)
519	
520		// 制造一连串失败操作，然后重开文件，确认没有半份记录。
521		_, _ = l.Register(RegisterInput{ID: " ", Name: "x", AllowedError: 1})
522		_, _ = l.Register(RegisterInput{ID: "M-1", Name: "x", AllowedError: 1})
523		_, _, _ = l.AddCertificate(CertificateInput{
524			InstrumentID: "M-1", Number: "C-X", CalDate: "not-a-date",
525			Expiry: "2027-01-01", Method: "m", Error: 0, Summary: "s",
526		})
527		_, _, _ = l.AddCertificate(CertificateInput{
528			InstrumentID: "M-1", Number: "C-X", CalDate: "2026-01-01",
529			Expiry: "2026-01-01", Method: "m", Error: 0, Summary: "s",
530		})
531		_, _ = l.RequestUse("GHOST")
532	
533		reopened, err := openAt(path, clock.now)
534		if err != nil {
535			t.Fatalf("reopen: %v", err)
536		}
537		if len(reopened.Instruments()) != 1 {
538			t.Fatalf("重开后器具数量异常：%d", len(reopened.Instruments()))
539		}
540		if len(reopened.data.Certificates) != 0 || len(reopened.data.Usage) != 0 {
541			t.Fatalf("重开后发现半份记录：证书 %d 使用 %d",
542				len(reopened.data.Certificates), len(reopened.data.Usage))
543		}
544	}
545	
546	func mustRegister(t *testing.T, l *Ledger, id, name string, allowed float64) {
547		t.Helper()
548		if _, err := l.Register(RegisterInput{ID: id, Name: name, AllowedError: allowed}); err != nil {
549			t.Fatalf("register %s: %v", id, err)
550		}
551	}
552	
553	func mustAddCert(t *testing.T, l *Ledger, in CertificateInput) {
554		t.Helper()
555		if _, _, err := l.AddCertificate(in); err != nil {
556			t.Fatalf("add cert %s: %v", in.Number, err)
557		}
558	}
559	
560	func containsReason(reasons []string, sub string) bool {
561		for _, r := range reasons {
562			if strings.Contains(r, sub) {
563				return true
564			}
565		}
566		return false
567	}
568	
569	func sameReasons(a, b []string) bool {
570		if len(a) != len(b) {
571			return false
572		}
573		for i := range a {
574			if a[i] != b[i] {
575				return false
576			}
577		}
578		return true
579	}
