26		clock.t = mustDate(t, "2026-10-03")
27		first, err := l.ReschedulePlan("P-1", "2026-10-20", "实验室排期冲突")
28		if err != nil {
29			t.Fatalf("首次改期应成功: %v", err)
30		}
