48		if p2, err := l.ReschedulePlan("P-1", "2026-10-20", "同日重申"); err == nil || p2 != nil {
49			t.Fatalf("同日改期写盘失败也应报保存错误且不返回计划：err=%v plan=%v", err, p2)
50		}
51	
52		// 文件仍不可保存时再次提交 11-05：仍报保存失败，而不是以任何方式成功。
53		if p2, err := l.ReschedulePlan("P-1", "2026-11-05", "实验室改造延期"); err == nil || p2 != nil {
54			t.Fatalf("再次提交应仍报保存失败：err=%v plan=%v", err, p2)
55		}
