95		r, err := l.Review("M-1")
96		if err != nil {
97			t.Fatalf("review: %v", err)
98		}
99		if len(r.Plans) != 1 || r.Plans[0].PlannedDate != "2026-10-20" ||
100			r.Plans[0].Marker != TodoToday || len(r.Plans[0].Changes) != 1 {
101			t.Fatalf("核对结果应与失败前一致：%+v", r.Plans)
102		}
103		views, err := l.Plans("M-1")
104		if err != nil || len(views) != 1 || views[0].PlannedDate != "2026-10-20" ||
